/** Generated by scaffold-crud-pages. Query hooks for CartItem.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchCartItemList,
  fetchCartItemById,
  createCartItem,
  updateCartItem,
  deleteCartItem,
  type FetchCartItemListParams,
} from '~/services/httpServices/cartItemService';
import type { CreateCartItemRequest, UpdateCartItemRequest } from '~/types/cart-item';

const DOMAIN = 'cartItem';

export function useCartItemList(params?: FetchCartItemListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchCartItemList(params),
  });
}

export function useCartItem(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchCartItemById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateCartItem() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateCartItemRequest) => createCartItem(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateCartItem() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateCartItemRequest }) =>
      updateCartItem(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteCartItem() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteCartItem(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
